// Theatre History — the eighth workspace (owner handoff, 2026-11-03).
//
// Twenty-two lessons walking the history of the form as a working actor
// meets it. The prose is Frankie's supplied handoff bundle
// (speechcraft-theatre-history-and-repertoire-for-claude.zip, 3 November
// 2026): twenty-two lessons drafted from Crash Course Theater transcripts
// plus a separately researched Vaudeville lesson. Nothing was shortened
// or summarised — the handoff's own instruction, and the conversion is
// checked against the source word count rather than eyeballed.
//
// WHAT THE CONVERSION CHANGED, AND NOTHING ELSE:
//   * house style — no em dashes, no contractions, curly quotes;
//   * inline markup removed, since the renderer escapes everything and
//     there is no inline emphasis anywhere in this app's lesson copy;
//   * every external link gave up its URL and kept its words. A source
//     cited mid-paragraph now reads as the institution's name; the URLs
//     are preserved in `sources`, which the owner reads in #review and
//     no learner surface renders. House sources policy, unchanged.
//
// THIS COURSE NAMES PEOPLE, AND THAT IS THE POINT OF IT.
// The house rule is no practitioner named in a lesson body, and it is
// kept where it means something: no acting technique here is attributed
// to a modern teacher, and no living person is named. But a history of
// theatre that cannot say Aeschylus, Molière, Zeami, Chekhov, Brecht or
// Bert Williams is not a history of theatre. Playwrights were always
// nameable (see the character-course house-style note); this course
// extends that to the historical figures its own titles are built from.
// Same category as Sources & Credits and Further Reading: names belong
// where they are the subject, not where they are an authority.
//
// GATED. THEATRE_LIVE is false in js/views/context.js and every record
// here is UNAPPROVED. The handoff says so in its own words — "editorial
// drafts, not a publication-ready scholarly edition", "verify historical
// claims before publication", "these files do not authorize deployment"
// — and Claude may never approve his own or anyone else's writing. The
// course needs an owner editorial entry in js/data/speech/reviews.js per
// lesson before a learner sees a word of it, and the reviewer this
// material actually wants is a theatre historian: `requiredReviewer` says
// 'theatre-history' and awaitingSpecialist() stays true.
//
// WRITTEN ONLY and NEVER SCORED, like Acting, Character and Shakespeare.
// The knowledge checks print their own answers; nothing is marked.
//
// IDS ARE PERMANENT from the first push. Progress, the review ledger and
// the audio flags all key on them.

export const THEATRE_PRINCIPLE =
  'Theatre has no agreed first moment and no single tradition. Walk the history as a working actor: what each form asked of a performer, and what it left behind that you can still use.';

export const THEATRE_MODULES = [
  { n: 1, id: 'th-origins', title: 'What Counts as Theatre',
    blurb: 'No agreed first moment and five competing theories: ritual, myth, clowning, play and the urge to imitate, and what changes when an ordinary action is framed for someone to watch.' },
  { n: 2, id: 'th-greeks', title: 'The Greeks',
    blurb: 'The festival that turned a chorus into a city arguing with itself, the vocabulary Aristotle built from it, and the comedy that made authority ridiculous.' },
  { n: 3, id: 'th-rome', title: 'Rome and the Medieval Stage',
    blurb: 'A form crossing into another society, the comedy and tragedy Rome made of it, and the long argument about whether theatre ever went away.' },
  { n: 4, id: 'th-asia', title: 'Classical Theatre of Japan',
    blurb: 'Two traditions built on precision rather than illusion: the unseen made present, and a character shared between several performers.' },
  { n: 5, id: 'th-earlymodern', title: 'The Early Modern Stage',
    blurb: 'Disguise, recognition and uncertain happy endings; and the comedy that got close enough to power to be banned.' },
  { n: 6, id: 'th-america19', title: 'Nineteenth-Century America',
    blurb: 'Who was permitted to make the image, and the variety industry that taught a performer how to hold a room in nine minutes.' },
  { n: 7, id: 'th-modern', title: 'Moscow, Dublin, New York, Harlem',
    blurb: 'Life beneath the lines, a national theatre arguing with its own audience, the small American stages that changed what a play could be, and a community taking control of how it was shown.' },
  { n: 8, id: 'th-argument', title: 'Brecht to Boal',
    blurb: 'Making the familiar strange, the promise that does not arrive, the stages built outside the institutions, and theatre used to rehearse change.' },
];

